import java.util.*;

class Solution {
  public int getFood(char[][] grid) {
    int m = grid.length, n = grid[0].length;
    Deque<int[]> q = new ArrayDeque<>();
    for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) if (grid[i][j] == '*') q.add(new int[] {i, j});
    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    for (int steps = 1; !q.isEmpty(); steps++) {
      for (int size = q.size(); size > 0; size--) {
        int[] c = q.poll();
        for (int[] d : dirs) {
          int x = c[0] + d[0], y = c[1] + d[1];
          if (x < 0 || y < 0 || x >= m || y >= n || grid[x][y] == 'X' || grid[x][y] == '*') continue;
          if (grid[x][y] == '#') return steps;
          grid[x][y] = 'X';
          q.add(new int[] {x, y});
        }
      }
    }
    return -1;
  }
}
